setup:
SIM.load('trisolaris');
for (let i = 0; i < 3; i++) SIM.frame(1/60);
SIM.setCamMode('surface');
SIM.stage.setLocalTime('noon');
SIM.state.timeScale = 0;

SIM.setBand(3);
SIM.scene.children.slice().forEach(c => SIM.scene.remove(c));
const orig = SIM.renderer.render.bind(SIM.renderer);
SIM.renderer.render = (s, c) => { const m = s.children[0] && s.children[0].material;
  if (m && m.uniforms && m.uniforms.uSunDir) window.__skyU = m.uniforms; return orig(s, c); };

dump:
(() => {
 const S = SIM.state, T = SIM.THREE;
 const home = S.bodies.find(b => b.id === S.homeId);
 const g = home.viz.group;
 const U = window.__skyU, v = k => U[k].value;
 const arr = x => (x.toArray ? x.toArray() : (x.r !== undefined ? [x.r, x.g, x.b] : x));
 const o = SIM.observer;
 const fwd = SIM.camera.getWorldDirection(new T.Vector3());
 const cl = S.climate;
 return {
  home: { scenePos: g.position.toArray(), R: home.viz.R, spinPhase: home.spinPhase,
          quat: g.getWorldQuaternion(new T.Quaternion()).toArray() },
  suns: S.suns.map(s => ({ name: s.body.name, posScene: s.posScene.toArray(),
          color: [s.color.r, s.color.g, s.color.b], intensity: s.intensity, angRadius: s.angRadius })),
  observer: { latitude: o.latitude, azimuth: o.azimuth, elevation: o.elevation, fov: o.fov,
          up: o.up.toArray(), north: o.north.toArray(), eye: o.eye.toArray(), forward: fwd.toArray() },
  exposure: v('uExposure'), uTime: v('uTime'),
  climate: cl ? { ice: cl.ice, T: cl.T, clouds: cl.clouds, humidity: cl.humidity, storm: cl.storm } : null,
  sky: S.sky, band: S.band,
  sceneT: Math.max(0, ...S.bodies.filter(b => b.type === 'star' || b.type === 'white-dwarf').map(b => b.teff || 0)) || 5800,
  web_uniforms: { uSunDir: v('uSunDir').map(arr), uSunColor: v('uSunColor').map(arr), uSunInt: Array.from(v('uSunInt')),
    uSunAng: Array.from(v('uSunAng')), uSunCount: v('uSunCount'), uUp: arr(v('uUp')), uNorth: arr(v('uNorth')),
    uFov: v('uFov'), uAspect: v('uAspect'), uIce: v('uIce'), uScorch: v('uScorch'), uClouds: v('uClouds'),
    uHumidity: v('uHumidity'), uStorm: v('uStorm'), uExposure: v('uExposure'), uTime: v('uTime'),
    uCamMat: Array.from(v('uCamMat').elements) },
 };
})()

